import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import { Palette, Zap, Moon, Sun, Layout, Code, Sparkles } from 'lucide-react';

function App() {
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const features = [
    {
      icon: <Palette size={24} />,
      title: "Palette de couleurs",
      description: "Accédez à une palette de couleurs complète."
    },
    {
      icon: <Moon size={24} />,
      title: "Mode sombre/clair",
      description: "Basculez entre les modes avec mémoire automatique."
    },
    {
      icon: <Layout size={24} />,
      title: "Design responsive",
      description: "Une interface qui s’adapte à tous les écrans."
    },
    {
      icon: <Zap size={24} />,
      title: "Performances optimisées",
      description: "Chargement rapide et structure propre."
    },
    {
      icon: <Code size={24} />,
      title: "Code propre",
      description: "React facile à maintenir."
    },
    {
      icon: <Sparkles size={24} />,
      title: "Animations fluides",
      description: "Expérience utilisateur agréable."
    }
  ];

  const colorSections = [
    { name: "Primaire", color: "primary" },
    { name: "Secondaire", color: "secondary" },
    { name: "Accentuation", color: "accent" },
    { name: "Neutre", color: "neutral" }
  ];

  return (
    <div>
      <Header darkMode={darkMode} toggleDarkMode={toggleDarkMode} />

      <main>

        {/* Hero */}
        <section>
          <h1>Application Moderne</h1>
          <p>Une application React sans styles Tailwind pour que tu appliques ton propre design.</p>
          <button>Commencer maintenant</button>
          <button>En savoir plus</button>
        </section>

        {/* Palette */}
        <section>
          <h2>Palette de couleurs</h2>
          {colorSections.map((section) => (
            <div key={section.color}>
              <h3>{section.name}</h3>
              {[50, 100, 200, 300, 400, 500, 600, 700, 800, 900].map((shade) => (
                <div key={shade}>
                  {section.color}-{shade}
                </div>
              ))}
            </div>
          ))}
        </section>

        {/* Fonctionnalités */}
        <section>
          <h2>Fonctionnalités principales</h2>

          {features.map((feature, index) => (
            <div key={index}>
              {feature.icon}
              <h3>{feature.title}</h3>
              <p>{feature.description}</p>
            </div>
          ))}
        </section>

        {/* Simulation Mode sombre */}
        <section>
          <h2>Mode sombre & clair</h2>
          <p>Appuyez pour changer :</p>

          <button onClick={toggleDarkMode}>
            {darkMode ? "Mode clair" : "Mode sombre"}
          </button>

          <p>Mode actuel : {darkMode ? "sombre" : "clair"}</p>
        </section>

        {/* Footer */}
        <footer>
          <h3>ReactUI</h3>
          <p>&copy; {new Date().getFullYear()} ReactUI — Tous droits réservés.</p>
        </footer>
      </main>
    </div>
  );
}

export default App;
